def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Find monochromatic connected components.
    seen = set()
    comps = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.setdefault(color, []).append(cells)

    # The long, straight/turning stripe is the color key.
    key_color, key_cells = max(
        ((color, cells) for color, groups in comps.items() for cells in groups),
        key=lambda item: len(item[1])
    )
    keyset = set(key_cells)

    # Recolor the non-background component bordering that stripe.
    candidates = []
    for color, groups in comps.items():
        if color == key_color:
            continue
        for cells in groups:
            touching = sum(
                (r+dr, c+dc) in keyset
                for r, c in cells
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1))
            )
            if touching:
                candidates.append((touching, len(cells), cells))
    if candidates:
        cells = max(candidates, key=lambda x: (x[0], x[1]))[2]
        for r, c in cells:
            out[r][c] = key_color
    return out
